create table if not exists public.spike_circle_invites(circle_id uuid not null references public.spike_circles(id) on delete cascade, inviter_id uuid not null references auth.users(id) on delete cascade, invitee_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), accepted_at timestamptz, primary key(circle_id,invitee_id));
alter table public.spike_circle_invites enable row level security;
revoke all on public.spike_circle_invites from anon,public,authenticated;
create or replace function public.spike_circle_invite(p_circle_id uuid,p_invitee_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); begin if uid is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.spike_circle_members where circle_id=p_circle_id and user_id=uid and role='owner') then raise exception 'Only the Circle owner can invite'; end if; if p_invitee_id=uid then raise exception 'Choose another person'; end if; if not exists(select 1 from public.friendships f where(f.user_id=uid and f.friend_id=p_invitee_id)or(f.user_id=p_invitee_id and f.friend_id=uid)) then raise exception 'You can invite friends only'; end if; insert into public.spike_circle_invites(circle_id,inviter_id,invitee_id) values(p_circle_id,uid,p_invitee_id) on conflict(circle_id,invitee_id) do update set inviter_id=excluded.inviter_id,created_at=now(),accepted_at=null; insert into public.notifications(user_id,type,data,priority,event_key,group_key) values(p_invitee_id,'spike_circle_invite',jsonb_build_object('circle_id',p_circle_id,'from_user_id',uid),'high','spike_circle_invite:'||p_circle_id::text||':'||p_invitee_id::text,'spike_circle:'||p_circle_id::text); return jsonb_build_object('ok',true); end $$;
create or replace function public.spike_circle_accept_invite(p_circle_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); begin if uid is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.spike_circle_invites where circle_id=p_circle_id and invitee_id=uid and accepted_at is null) then raise exception 'Invite not found'; end if; insert into public.spike_circle_members(circle_id,user_id) values(p_circle_id,uid) on conflict do nothing; update public.spike_circle_invites set accepted_at=now() where circle_id=p_circle_id and invitee_id=uid; return jsonb_build_object('ok',true); end $$;
create or replace function public.spike_circle_invites_list() returns jsonb language sql security definer set search_path=public,pg_temp as $$ select coalesce(jsonb_agg(jsonb_build_object('circle_id',i.circle_id,'circle_name',c.name,'inviter_id',i.inviter_id,'inviter_name',coalesce(p.display_name,p.username,'SPIKE User'),'created_at',i.created_at) order by i.created_at desc),'[]'::jsonb) from public.spike_circle_invites i join public.spike_circles c on c.id=i.circle_id join public.profiles p on p.id=i.inviter_id where i.invitee_id=(select auth.uid()) and i.accepted_at is null; $$;
revoke execute on function public.spike_circle_invite(uuid,uuid),public.spike_circle_accept_invite(uuid),public.spike_circle_invites_list() from public,anon;
grant execute on function public.spike_circle_invite(uuid,uuid),public.spike_circle_accept_invite(uuid),public.spike_circle_invites_list() to authenticated;
